  Syntagma(id: 'cas-prep-duplex-013', text: 'servī in {agrōs} eunt', lemmaId: 'ager', casus: Casus.accusativus, number: Numerus.pluralis, constructio: Constructio.inAccusativus, functio: Functio.locusQuo, tags: {'cas-prep-duplex'}, note: 'Eō verbum mōtūs est: in agrōs accūsātīvus plūrālis, quō.'),
