  Syntagma(id: 'cas-prep-abl-008', text: 'servus sine {pecūniā} venit', lemmaId: 'pecunia', casus: Casus.ablativus, number: Numerus.singularis, functio: Functio.praepositio, tags: {'cas-prep-abl'}, note: 'Sine ablātīvum semper regit: sine pecūniā.'),
  Syntagma(id: 'cas-prep-abl-009', text: 'cōnsul cōram {populō} loquitur', lemmaId: 'populus', casus: Casus.ablativus, number: Numerus.singularis, functio: Functio.praepositio, tags: {'cas-prep-abl'}, note: 'Cōram ablātīvum semper regit: cōram populō.'),
  Syntagma(id: 'cas-prep-abl-010', text: 'Mēdus prae {metū} tacet', lemmaId: 'metus', casus: Casus.ablativus, number: Numerus.singularis, functio: Functio.praepositio, tags: {'cas-prep-abl'}, note: 'Prae ablātīvum semper regit: prae metū (quārtae dēclīnātiōnis).'),
