  Syntagma(id: 'cas-prep-abl-013', text: 'Mēdus {urbem} relinquit', lemmaId: 'urbs', casus: Casus.accusativus, number: Numerus.singularis, functio: Functio.obiectum, tags: {'cas-prep-abl'}, note: 'Sine praepositiōne: urbem accūsātīvus obiectum verbī relinquō.'),
