  Syntagma(id: 'cas-prep-abl-018', text: 'puer {digitō} litterās scrībit', lemmaId: 'digitus', casus: Casus.ablativus, number: Numerus.singularis, functio: Functio.instrumentum, tags: {'cas-prep-abl'}, note: 'Ablātīvus īnstrūmentī sine praepositiōne: digitō scrībit.'),

