  Syntagma(id: 'cas-prep-acc-019', text: 'puerī {mēnsam} portant', lemmaId: 'mensa', casus: Casus.accusativus, number: Numerus.singularis, functio: Functio.obiectum, tags: {'cas-prep-acc'}, note: 'Sine praepositiōne: mēnsam accūsātīvus obiectum verbī portō.'),
